import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-11-19","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-11-19","date":"2025-11-19T00:00:00.000Z","updated":"2025-12-04T00:00:00.000Z","tags":["Ceph","Distributed Storage","RGW Refactoring","C++20 Coroutines","DDUP"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-19.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-19.md","lastUpdated":1780460162000}'),n={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-19.md"};function s(i,t,l,g,p,d){return a(),r("div",null,[...t[0]||(t[0]=[o('<h3 id="ceph-rgw-重构会议纪要" tabindex="-1">Ceph RGW 重构会议纪要 <a class="header-anchor" href="#ceph-rgw-重构会议纪要" aria-label="Permalink to &quot;Ceph RGW 重构会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1"><strong>会议主题</strong> <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;**会议主题**&quot;">​</a></h4><p>本次会议主要讨论了 Ceph RGW 的几个重要改进，包括 DDUP 功能改进、服务器端加密（SSE）复制支持以及 C++20 协程代码问题。</p><h3 id="_1-ddup-功能改进" tabindex="-1"><strong>1. DDUP 功能改进</strong> <a class="header-anchor" href="#_1-ddup-功能改进" aria-label="Permalink to &quot;**1. DDUP 功能改进**&quot;">​</a></h3><p><strong>讨论重点</strong>：</p><ul><li><strong>版本对象处理</strong>：将每个版本对象视为独立实体，支持 DDUP 操作，无需介入生命周期管理。</li><li><strong>Split Head 优化</strong>：支持小至 8KB/4KB 对象的去重，涉及 manifest 操作的代码需专家协助审查。</li><li><strong>加密与压缩对象</strong>：当前 DDUP 不支持加密和压缩对象，未来可能扩展支持。</li></ul><h3 id="_2-服务器端加密-sse-复制支持" tabindex="-1"><strong>2. 服务器端加密（SSE）复制支持</strong> <a class="header-anchor" href="#_2-服务器端加密-sse-复制支持" aria-label="Permalink to &quot;**2. 服务器端加密（SSE）复制支持**&quot;">​</a></h3><p><strong>讨论重点</strong>：</p><ul><li><strong>Marcus 的 PR 长期停滞</strong>：涉及 SSE 复制功能，部分属性更新问题未解决。</li><li><strong>Cena 的替代方案</strong>：覆盖单区域和多区域复制，已通过 S3 测试。</li><li><strong>决策</strong>：优先合并 Cena 的单区域复制 PR，多区域复制的重加密功能后续通过独立 PR 实现。</li></ul><h3 id="_3-c-20-协程代码问题" tabindex="-1"><strong>3. C++20 协程代码问题</strong> <a class="header-anchor" href="#_3-c-20-协程代码问题" aria-label="Permalink to &quot;**3. C++20 协程代码问题**&quot;">​</a></h3><p><strong>讨论重点</strong>：</p><ul><li><strong>未使用的协程代码</strong>：发现部分已合并的协程代码未被调用，需进一步验证。</li><li><strong>元数据同步原型</strong>：Casey 将重新开放相关 PR，明确活跃开发分支。</li><li><strong>后续行动</strong>：Jane 提交具体代码链接供 Adam 审查，Casey 协助更新元数据同步协程原型。</li></ul><h3 id="行动计划-action-items" tabindex="-1"><strong>行动计划（Action Items）</strong> <a class="header-anchor" href="#行动计划-action-items" aria-label="Permalink to &quot;**行动计划（Action Items）**&quot;">​</a></h3><p>| 任务 | 负责人 | 状态 | ||--|| | DDUP Split Head PR 审查 | Gabby、Matt、Casey | 待启动 | | SSE 单区域复制 PR 合并 | Cena | 待测试 | | 多区域复制重加密 PR | Cena | 后续阶段 | | C++20 协程代码验证 | Adam、Jane | 进行中 | | 元数据同步协程分支更新 | Casey | 待完成 |</p><p><strong>关键词保留</strong></p><ul><li><strong>技术术语</strong>：DDUP、manifest、SSE、multi-site、C++20 coroutines、S3 API、PR。</li><li><strong>Ceph 组件</strong>：RADOS、librados、CRUSH、OSD、PG。</li></ul><p><strong>下次会议重点</strong>：DDUP 审查进展、SSE 复制测试结果、协程代码优化。<br><strong>会议结束时间</strong>：议题覆盖完毕，无其他问题。</p>',17)])])}const _=e(n,[["render",s]]);export{c as __pageData,_ as default};
